  function consumeContractStock(def,qty){qty=Math.max(0,Number(qty||0));if(C.resource(def.resourceId)<qty)return null;const lots=C.state.materialLots?.[def.resourceId];if(!hasFarmCriteria(def)){if(!Array.isArray(lots)){if(!C.consumeResource(def.resourceId,qty,'Livraison contrat Fermier'))return null;return{avgQuality:0};}const totalLots=lots.reduce((n,l)=>n+Number(l.quantity||0),0),common=Math.max(0,C.resource(def.resourceId)-totalLots);let remaining=Math.max(0,qty-common),qualitySum=0,used=0;if(remaining>0){for(const l of [...lots].sort((a,b)=>Number(a.quality||0)-Number(b.quality||0))){if(remaining<=0)break;const take=Math.min(remaining,Number(l.quantity||0));l.quantity-=take;remaining-=take;used+=take;qualitySum+=take*Number(l.quality||0);}if(remaining>0)return null;C.state.materialLots[def.resourceId]=lots.filter(l=>Number(l.quantity||0)>0);}C.state.resources[def.resourceId]=Math.max(0,C.resource(def.resourceId)-qty);C.recordInventoryEvent('out',def.resourceId,qty,'Livraison contrat Fermier');return{avgQuality:used?qualitySum/used:0};}
    let remaining=qty,qualitySum=0,used=0;const compatible=compatibleLots(def).slice().sort((a,b)=>Number(a.quality||0)-Number(b.quality||0));for(const l of compatible){if(remaining<=0)break;const take=Math.min(remaining,Number(l.quantity||0));l.quantity-=take;remaining-=take;used+=take;qualitySum+=take*Number(l.quality||0);}if(remaining>0)return null;C.state.materialLots[def.resourceId]=(lots||[]).filter(l=>Number(l.quantity||0)>0);C.state.resources[def.resourceId]=Math.max(0,C.resource(def.resourceId)-qty);C.recordInventoryEvent('out',def.resourceId,qty,'Livraison contrat Fermier');return{avgQuality:used?qualitySum/used:0};}
  function contractRemarkable(def,delivered){const c=farmCriteria(def);return !!delivered&&Number(c.qualityMin||0)>0&&Number(delivered.avgQuality||0)>=Number(c.qualityMin||0)+8;}
  function contractEligible(def){if(!def)return false;const client=C.jobClient(def.clientId),masterOk=!def.requiresMaster||S.masterCertified,clientOk=!client||((!client.masterOnly||S.masterCertified)&&rankOrder()>=Number(client.minRank||0));return masterOk&&clientOk&&rankOrder()>=Number(def.minRank||0)&&S.level>=Number(def.minLevel||1)&&S.reputation>=Number(def.minReputation||0)&&clientTrust(def.clientId)>=Number(def.minTrust||0)&&(!def.requiredLandId||landKnown(def.requiredLandId));}
  function activeContractLimit(){return Math.max(3,3+Math.round(careerEffect('activeContractSlots')));}
  function cleanupOffers(){const t=Date.now();S.contractOffers=S.contractOffers.filter(o=>Number(o.expiresAt||0)>t);}
  function generateContractOffers(force=false){cleanupOffers();const t=Date.now();if(!force&&t-Number(S.lastContractRefresh||0)<12000)return false;S.lastContractRefresh=t;const occupied=new Set([...S.contractOffers,...S.activeContracts].map(x=>x.contractId)),pool=farmerContracts().filter(d=>contractEligible(d)&&!occupied.has(d.id));for(let i=pool.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]];}let changed=false;while(S.contractOffers.length<4&&pool.length){const d=pool.shift();S.contractOffers.push({id:uid(),contractId:d.id,createdAt:t,expiresAt:t+90000});changed=true;}return changed;}
  function failContract(active,reason='Délai dépassé'){const d=C.jobContract(active.contractId);if(!d)return;const f=d.failure||{};S.reputation=clampRep(S.reputation-Number(f.reputation||0));S.clientTrust[d.clientId]=clampRep(clientTrust(d.clientId)-Number(f.trust||0));S.failedContracts++;S.contractHistory.unshift({contractId:d.id,status:'failed',at:Date.now(),reason});S.contractHistory=S.contractHistory.slice(0,50);C.log(`⚠️ Contrat Fermier échoué — ${d.name}. ${reason}.`);}
  function contractTick(){cleanupOffers();const t=Date.now(),expired=S.activeContracts.filter(a=>Number(a.end||0)<=t);let changed=false;if(expired.length){for(const a of expired)failContract(a);const gone=new Set(expired.map(a=>a.id));S.activeContracts=S.activeContracts.filter(a=>!gone.has(a.id));S.lastContractRefresh=0;changed=true;}if(generateContractOffers())changed=true;if(changed)C.save();}
  window.farmerAcceptContract=id=>{const o=S.contractOffers.find(x=>x.id===id),d=C.jobContract(o?.contractId);if(!o||!d||!contractEligible(d)||S.activeContracts.length>=activeContractLimit())return;S.contractOffers=S.contractOffers.filter(x=>x.id!==id);S.activeContracts.push({id:uid(),contractId:d.id,acceptedAt:Date.now(),end:Date.now()+Number(d.duration||180)*1000});C.log(`📜 Contrat Fermier accepté : ${d.name}.`);C.save();render();};
