  window.farmerRequestEndorsement=id=>{const c=C.jobClient(id);if(!canRequestEndorsement(c))return;S.endorsements.push(id);S.stats.endorsements=S.endorsements.length;S.reputation=clampRep(S.reputation+2);C.gainVillageXp(5);C.log(`✍️ Recommandation obtenue : ${c.name} signe le dossier de maîtrise du Fermier.`);C.save();render();};
  window.farmerDeliverContract=id=>{const a=S.activeContracts.find(x=>x.id===id),d=C.jobContract(a?.contractId);if(!a||!d||compatibleContractQty(d)<Number(d.quantity||1))return;const delivered=consumeContractStock(d,Number(d.quantity||1));if(!delivered)return;const remarkable=contractRemarkable(d,delivered),bonus=remarkable?1.2:1,reward=d.reward||{},renownTreasury=Math.max(0,Math.round(Number(reward.treasury||0)*careerEffect('contractReward'))),trustGain=Math.max(0,Math.round((Number(reward.trust||0)+(remarkable?1:0))*(1+careerEffect('trustGain'))));C.gainJobXp('farmer',Math.round(Number(reward.jobXp||0)*bonus));C.gainVillageXp(Math.round(Number(reward.villageXp||0)*bonus));C.gainMastery('farmer',remarkable?4:2);S.reputation=clampRep(S.reputation+Number(reward.reputation||0)+(remarkable?2:0));S.clientTrust[d.clientId]=clampRep(clientTrust(d.clientId)+trustGain);C.state.treasury=Math.max(0,Number(C.state.treasury||0)+Math.round(Number(reward.treasury||0)*bonus)+renownTreasury);S.completedContracts++;if(d.requiredLandId||Number(d.minRank||0)>=4)S.stats.prestigeContracts++;if(d.requiresMaster)S.stats.masterContracts++;if(remarkable)S.stats.remarkableContracts++;S.contractHistory.unshift({contractId:d.id,status:'delivered',at:Date.now(),remarkable,avgQuality:delivered.avgQuality});S.contractHistory=S.contractHistory.slice(0,50);S.activeContracts=S.activeContracts.filter(x=>x.id!==id);S.lastContractRefresh=0;C.log(`${remarkable?'⭐ Livraison remarquable':'📦 Contrat Fermier livré'} : ${d.name}. Réputation ${Math.round(S.reputation)}/100.${renownTreasury?` Prime de renommée +${renownTreasury} couronnes.`:''}`);C.save();render();};
  function landRequirements(x){const rows=[],add=(label,have,need)=>rows.push({label,have:Number(have||0),need:Number(need||0),ok:Number(have||0)>=Number(need||0)});add('Niveau Fermier',S.level,x.minLevel||1);add('Grade',rankOrder(),x.minRank||0);add('Réputation',S.reputation,x.minReputation||0);add('Contrats réussis',S.completedContracts,x.minContracts||0);if(Number(x.minExcellentUnits||0)>0)add('Unités excellentes',S.stats.excellentUnits||0,x.minExcellentUnits);if(Number(x.minRareHarvests||0)>0)add('Récoltes rares',S.stats.rareHarvests||0,x.minRareHarvests);if(Number(x.minPrestigeHarvests||0)>0)add('Récoltes de prestige',S.stats.prestigeHarvests||0,x.minPrestigeHarvests);for(const id of x.requiresLands||[])rows.push({label:`Terre ${landDef(id)?.name||id}`,have:landKnown(id)?1:0,need:1,ok:landKnown(id)});return rows;}
  function canDiscoverLand(x){return !!x?.unique&&!landKnown(x.id)&&!S.activeLandSurvey&&landRequirements(x).every(r=>r.ok);}
  window.farmerDiscoverLand=id=>{const x=landDef(id);if(!canDiscoverLand(x))return;const duration=Math.max(5,Number(x.duration||15));S.activeLandSurvey={landId:id,start:now(),end:now()+duration*1000,duration};C.log(`🗺️ Reconnaissance agricole lancée : ${x.name}.`);C.save();renderHighLevel();};
  function completeLandSurvey(){const t=S.activeLandSurvey;if(!t||now()<Number(t.end||0))return false;const x=landDef(t.landId);S.activeLandSurvey=null;if(!x||landKnown(x.id))return false;S.knownUniqueLands.push(x.id);S.stats.uniqueLandsDiscovered=Math.max(Number(S.stats.uniqueLandsDiscovered||0)+1,S.knownUniqueLands.length);for(const [rid,qty] of Object.entries(x.seedRewards||{})){const accepted=C.addResource(rid,Number(qty||0),`Découverte agricole : ${x.name}`);if(accepted)C.log(`🌱 ${accepted} ${res(rid)?.name||rid} récupérée(s) sur ${x.name}.`);}for(const [k,v] of Object.entries(x.reward||{})){if(k==='jobXp')C.gainJobXp('farmer',v);else if(k==='villageXp')C.gainVillageXp(v);else if(k==='reputation')S.reputation=clampRep(S.reputation+Number(v||0));else if(k==='treasury')C.state.treasury+=Number(v||0);}ensurePlots();C.gainMastery('farmer',3);C.log(`🗺️ Terre unique reconnue : ${x.name}. Une parcelle spéciale y est désormais cultivable.`);C.evaluateAchievements?.();C.save();return true;}
  function highLevelTick(){return completeLandSurvey();}
  function renderHighLevel(){highLevelTick();const lands=uniqueLands(),known=lands.filter(x=>landKnown(x.id)),survey=S.activeLandSurvey,ready=lands.filter(canDiscoverLand).length;const summary=$('#farmHighLevelSummary');if(summary)summary.innerHTML=`<div class="highlevel-summary"><div><span>Terres uniques reconnues</span><b>${known.length}/${lands.length}</b></div><div><span>Reconnaissances disponibles</span><b>${ready}</b></div><div><span>Récoltes rares</span><b>${S.stats.rareHarvests||0}</b></div><div><span>Récoltes de prestige</span><b>${S.stats.prestigeHarvests||0}</b></div></div>${survey?`<div class="notice" style="margin-top:12px"><b>🗺️ Reconnaissance en cours : ${esc(landDef(survey.landId)?.name||survey.landId)}</b><br>Fin dans ${C.autonomyFormatDuration(Math.max(0,Number(survey.end||0)-now()))}. La progression est conservée si tu quittes l’écran.</div>`:'<div class="notice subtle" style="margin-top:12px"><b>Boucle haut niveau :</b> les récoltes excellentes et les contrats ouvrent des terres hors de l’exploitation commune. Chaque terre reconnue ajoute une parcelle permanente, fournit les premières semences rares et permet des contrats de prestige.</div>'}`;
    const host=$('#farmUniqueLands');if(host)host.innerHTML=`<div class="highlevel-sites">${lands.map(x=>{const unlocked=landKnown(x.id),rows=landRequirements(x),can=canDiscoverLand(x),rare=(x.cropIds||[]).map(id=>crop(id)).filter(Boolean),reward=x.reward||{},active=survey?.landId===x.id;return `<article class="highlevel-site ${unlocked?'unlocked':can?'ready':'locked'}"><div class="highlevel-site-head"><span>${x.icon||'🗺️'}</span><div><b>${esc(x.name)}</b><small>${unlocked?'✓ Reconnue — parcelle permanente disponible':active?'Reconnaissance en cours':can?'Reconnaissance disponible':'Conditions non remplies'}</small></div></div><p class="muted">${esc(x.description||'')}</p><div class="site-reqs">${rows.map(r=>`<div class="site-req ${r.ok?'ok':'missing'}"><span>${r.ok?'✓':'○'} ${esc(r.label)}</span><b>${Math.round(r.have)} / ${r.need}</b></div>`).join('')}</div><div class="site-reward"><span>XP +${reward.jobXp||0}</span><span>Village XP +${reward.villageXp||0}</span><span>Réputation +${reward.reputation||0}</span>${Object.entries(x.seedRewards||{}).map(([rid,q])=>`<span>${res(rid)?.icon||'🌱'} ${q} semence(s)</span>`).join('')}</div><div class="unique-land-crops">${rare.map(c=>`<span>${c.icon||'🌾'} ${esc(c.name)}</span>`).join('')}</div>${unlocked?'<div class="notice subtle">Cette terre apparaît maintenant dans l’onglet Activité comme parcelle spéciale. Les cultures ordinaires ne peuvent pas y être semées.</div>':`<button class="btn primary" onclick="farmerDiscoverLand('${x.id}')" ${!can?'disabled':''}>🗺️ Reconnaître la terre · ${x.duration||15}s</button>`}</article>`;}).join('')}</div>`;
    const rareHost=$('#farmRareCrops');if(rareHost)rareHost.innerHTML=`<div class="farm-info-grid rare-crop-grid">${rareCrops().map(c=>{const sid=(c.requiredSoilIds||[])[0],sd=soil(sid),unlocked=sid?landKnown(sid):true;return `<article class="${unlocked?'unlocked':'locked'} rare-crop-card"><span>${c.icon||'🌟'}</span><b>${esc(c.name)}</b><small>${unlocked?'Culture disponible':`🔒 ${esc(sd?.name||'terre unique à reconnaître')}`} · niv. ${c.minLevel}</small><p>${esc(c.description||'')}</p><em>Semence : ${res(c.seedResource)?.icon||'🌱'} ${esc(res(c.seedResource)?.name||c.seedResource)} · récolte : ${res(c.outputResource)?.icon||'🌾'} ${esc(res(c.outputResource)?.name||c.outputResource)}</em><div class="unique-site-badge">${esc(sd?.name||'Terre unique')} · qualité +${Number(sd?.qualityBonus||0)}</div></article>`;}).join('')}</div>`;}

  function puzzleEligible(trigger){return puzzles().filter(p=>p.trigger===trigger&&S.level>=Number(p.minLevel||1));}
  function maybePuzzle(trigger,payload){if(F.pendingPuzzle)return true;const choices=puzzleEligible(trigger);if(!choices.length)return false;const pp=choices[Math.floor(Math.random()*choices.length)];if(Math.random()*100>=Number(pp.chance||0))return false;F.pendingPuzzle={puzzleId:pp.id,trigger,payload,createdAt:now()};S.stats.puzzles++;renderPuzzle();C.save();return true;}
