  function actionWater(id,bypass=false,puzzleSuccess=null){updateAll();const p=F.plots.find(x=>x.id===id),c=crop(p?.cropId);if(!p||!['growing','mature'].includes(p.status))return;if(!bypass&&maybePuzzle('care',{plotId:id,cropId:c?.id}))return;if(!spend(farmEnergy(3,'care')))return;const g=selectedGesture('care',c),eff=gEffect(g,'waterEfficiency')+toolBonus('care','waterEfficiency')+gearEffect('waterEfficiency'),target=(Number(c?.optimalMoistureMin||45)+Number(c?.optimalMoistureMax||75))/2,base=28,smart=eff>0?Math.max(8,Math.min(base*(1+eff),Math.max(0,target-p.moisture)+8+base*eff*.35)):base,bonus=puzzleSuccess===true?5:puzzleSuccess===false?-5:0;p.moisture=clamp(p.moisture+smart+bonus);p.health=clamp(p.health+2+gEffect(g,'health')+toolBonus('care','healthBonus')+(puzzleSuccess===true?2:puzzleSuccess===false?-2:0));wearTool('care');S.stats.careActions++;gainSkill('cultivation',4);gainKnowledge(c?.id,2+gEffect(g,'knowledgeGain')+specEffect('knowledgeGain'));gainSoilKnowledge(p.soilId,1);useGesture(g,3);C.gainJobXp('farmer',2);C.log(`💧 Parcelle ${p.no} arrosée avec ${g?.name||'une méthode courante'}.`);C.save();render();}
