  function renderPlots(){updateAll();const cal=calendarState(),w=currentWeather();const strip=$('#farmClimateStrip');if(strip){const pending=eventLife().pending,ev=farmEvent(pending?.eventId);strip.innerHTML=`<div class="farm-climate-strip"><span>${cal.season?.icon||'🗓️'} <b>${esc(cal.season?.name||'Saison')}</b> · jour ${cal.day}/${SEASON_DAYS}</span><span>${w.icon||'🌤️'} <b>${esc(w.name||'Météo')}</b></span><span>Année ${cal.year}</span>${ev?`<button class="tiny-action farm-event-strip-alert" onclick="farmerOpenEvents()">${ev.icon||'⚠️'} ${esc(ev.name)} · décider</button>`:''}</div>`;}$('#farmPlotGrid').innerHTML=F.plots.map(plotCard).join('');bindGestureSelectors();document.querySelectorAll('[data-prepare]').forEach(b=>b.onclick=()=>actionPrepare(b.dataset.prepare));document.querySelectorAll('[data-sow]').forEach(b=>b.onclick=()=>{const id=b.dataset.sow,sel=document.querySelector(`[data-crop-select="${id}"]`);actionSow(id,sel?.value)});document.querySelectorAll('[data-water]').forEach(b=>b.onclick=()=>actionWater(b.dataset.water));document.querySelectorAll('[data-weed]').forEach(b=>b.onclick=()=>actionWeed(b.dataset.weed));document.querySelectorAll('[data-harvest]').forEach(b=>b.onclick=()=>actionHarvest(b.dataset.harvest));document.querySelectorAll('[data-treat-disease]').forEach(b=>b.onclick=()=>treatThreat(b.dataset.treatDisease,'disease'));document.querySelectorAll('[data-treat-pest]').forEach(b=>b.onclick=()=>treatThreat(b.dataset.treatPest,'pest'));}
