  function renderExploitation(){updateAll();const cal=calendarState(),w=currentWeather(),next=Math.max(0,cal.nextAt-now()),seasonCards=seasons().map(s=>`<article class="${s.id===cal.season?.id?'active-season':''}"><span>${s.icon||'🗓️'}</span><b>${esc(s.name)}</b><small>${Math.round(s.temperature||0)} °C · pluie ×${Number(s.rainfall||1).toFixed(2)} · évap. ×${Number(s.evaporation||1).toFixed(2)}</small><p>${esc(s.description||'')}</p></article>`).join('');$('#farmClimate').innerHTML=`<div class="farm-climate-summary"><div><span>Saison actuelle</span><b>${cal.season?.icon||'🗓️'} ${esc(cal.season?.name||'—')}</b><small>Année ${cal.year} · jour ${cal.day}/${SEASON_DAYS} · prochain jour dans ${C.autonomyFormatDuration(next)}</small></div><div><span>Météo</span><b>${w.icon||'🌤️'} ${esc(w.name||'—')}</b><small>${esc(w.description||'')} · changement dans ${C.autonomyFormatDuration(Math.max(0,Number(F.weather.until||0)-now()))}</small></div></div><div class="farm-season-grid">${seasonCards}</div>`;
    $('#farmRotationPanel').innerHTML=`<div class="farm-rotation-list">${F.plots.map(p=>{const hist=(p.rotationHistory||[]).slice(-3).reverse(),c=crop(p.cropId);return `<article><div><b>Parcelle ${p.no}</b><small>${esc(soil(p.soilId)?.name||'Sol')} · fertilité ${Math.round(p.fertility)}%</small></div>${c?`<p>Culture actuelle : ${c.icon||'🌱'} ${esc(c.name)} · ${esc(rotationLabel(p,c))}</p>`:'<p>Parcelle au repos : la fertilité remonte progressivement.</p>'}<div class="rotation-history">${hist.length?hist.map(h=>`<span>${crop(h.cropId)?.icon||'🌱'} ${esc(crop(h.cropId)?.name||h.cropId)}</span>`).join(''):'<span>Aucun précédent</span>'}</div></article>`}).join('')}</div><div class="notice subtle"><b>Principe :</b> répéter la même famille épuise le sol et réduit le rendement. Une légumineuse avant une céréale ou une racine améliore la rotation.</div>`;
    $('#farmThreatCards').innerHTML=`<div class="farm-threat-catalog">${threats().map(t=>`<article><span>${t.icon||'⚠️'}</span><div><b>${esc(t.name)}</b><small>${t.type==='disease'?'Maladie':'Ravageur'} · familles : ${(t.cropFamilies||[]).join(', ')||'toutes'}</small><p>${esc(t.description||'')}</p><em>${esc(t.treatment||'')}</em></div></article>`).join('')}</div><div class="farm-active-threats">${F.plots.filter(p=>p.disease||p.pest).map(p=>`<div><b>Parcelle ${p.no}</b>${activeThreatObjects(p).map(x=>`<span>${x.def.icon||'⚠️'} ${esc(x.def.name)} · ${Math.round(x.severity)}%</span>`).join('')}</div>`).join('')||'<div class="empty-state compact"><b>Aucune menace active</b><span>Les parcelles sont actuellement saines.</span></div>'}</div>`;}
  function renderKnowledge(){const mastered=crops().filter(c=>knowledgeLevel(c.id)>=3).length,soilMastered=soils().filter(sd=>knowledgeLevel(sd.id,true)>=3).length;$('#farmKnowledgeSummary').innerHTML=`<div class="knowledge-summary"><div><span>Cultures maîtrisées</span><b>${mastered}/${crops().length}</b></div><div><span>Sols maîtrisés</span><b>${soilMastered}/${soils().length}</b></div><div><span>Gestes pratiqués</span><b>${Object.values(S.stats.gestures).filter(v=>v>0).length}/${gestures().length}</b></div><div><span>Puzzles réussis</span><b>${S.stats.puzzlesWon}/${S.stats.puzzles}</b></div></div>`;$('#farmKnowledgeCards').innerHTML=`<div class="farm-knowledge-grid">${crops().map(c=>{const p=knowledgeProgress(c.id),g=gesture(c.recommendedGestureId),clues=c.clues||[];return `<article class="farm-knowledge-card k${p.lvl}"><div class="farm-knowledge-head"><span>${c.icon||'🌱'}</span><div><b>${esc(c.name)}</b><small>Difficulté ×${c.knowledgeDifficulty||1}</small></div><strong>${K_NAMES[p.lvl]}</strong></div><div class="progress"><i style="width:${p.pct}%"></i></div><small>${Math.floor(p.raw)} pts${p.next===null?' · connaissance complète':` · progression vers ${K_NAMES[p.lvl+1]}`}</small><div class="farm-knowledge-facts"><div><span>Repéré</span><b>${esc(c.description||'')}</b></div><div class="${p.lvl>=1?'':'unknown'}"><span>Reconnu</span><b>${p.lvl>=1?`${esc(c.agronomy||'')} · humidité ${c.optimalMoistureMin}–${c.optimalMoistureMax}%`:'Les besoins précis restent inconnus.'}</b></div><div class="${p.lvl>=2?'':'unknown'}"><span>Analysé</span><b>${p.lvl>=2?`${esc(c.behavior||'')} ${clues.length?`Indices : ${esc(clues.join(' · '))}.`:''}`:'Le comportement de la culture reste à analyser.'}</b></div><div class="${p.lvl>=3?'':'unknown'}"><span>Maîtrisé</span><b>${p.lvl>=3?`Affinités sols connues · geste conseillé : ${g?.icon||'🛠️'} ${esc(g?.name||'—')}. Bonus de savoir actif sur qualité et rendement.`:'Les affinités fines et le geste optimal restent à découvrir.'}</b></div></div></article>`}).join('')}</div>`;$('#farmSkillCards').innerHTML=`<div class="farm-skill-grid">${Object.entries(SKILLS).map(([k,d])=>{const lvl=skillLevel(k),xp=Number(S.skillXp[k]||0),next=skillNext(k),base=SKILL_THRESH[Math.max(0,lvl-1)],pct=next===null?100:clamp((xp-base)/(next-base)*100);return `<article class="farm-skill-card"><div class="farm-skill-head"><span>${d.icon}</span><div><b>${d.name}</b><small>Niveau technique ${lvl}/10</small></div><strong>${Math.floor(xp)} XP</strong></div><div class="progress"><i style="width:${pct}%"></i></div><p>${k==='soil'?'Améliore la préparation et la lecture des terres.':k==='cultivation'?'Améliore les soins, l’eau et la santé des cultures.':k==='harvest'?'Améliore rendement, qualité et récupération au tri.':'Améliore la régularité des transformations et la qualité des produits finis.'}</p></article>`}).join('')}</div>`;$('#farmGestureCards').innerHTML=`<div class="farm-gesture-grid">${gestures().map(g=>{const open=gestureUnlocked(g),m=gestureMastery(g.id),next=gestureNext(g.id);return `<article class="farm-gesture-card ${open?'':'locked'}"><div class="farm-gesture-head"><span>${g.icon||'🛠️'}</span><div><b>${esc(g.name)}</b><small>${g.phase} · ${SKILLS[g.skill]?.name||g.skill}</small></div><strong>${open?`M${m}/5`:'🔒'}</strong></div><p>${esc(g.description||'')}</p><div class="farm-gesture-meta"><span>Requis : niv. ${g.minLevel} · technique ${g.minSkill}</span><span>Pratiqué ${S.stats.gestures[g.id]||0} fois</span><span>${next===null?'Maîtrise maximale':`${Math.floor(S.gestureXp[g.id]||0)} / ${next} XP`}</span></div></article>`}).join('')}</div>`;}
  function renderCareer(){contractTick();const current=C.currentProfessionalRank('farmer'),next=C.nextProfessionalRank('farmer'),rows=next?rankRequirements(next):[],can=next&&rows.every(r=>r.ok),t=Date.now();$('#farmRankProgress').innerHTML=`<div class="rank-promotion-card ${can?'ready':''}"><div class="rank-promotion-head"><div><small>Grade actuel</small><h3>${current?.icon||'🌱'} ${esc(current?.name||C.jobRank('farmer'))}</h3><p>${esc(current?.description||'')}</p></div><div><small>Réputation</small><b>${Math.round(S.reputation)}/100</b></div></div>${next?`<div class="notice subtle"><b>Prochaine promotion : ${next.icon||'🎖️'} ${esc(next.name)}</b><br>${esc(next.description||'')}</div><div class="rank-checks">${rows.map(r=>`<div class="rank-check ${r.ok?'ok':'missing'}"><span>${r.ok?'✓':'○'} ${esc(r.label)}</span><strong>${Math.round(r.have)}/${r.need}</strong></div>`).join('')}</div><div class="rank-actions"><button class="btn primary" onclick="farmerPromote()" ${can?'':'disabled'}>🎖️ Valider la promotion</button></div>`:`<div class="notice"><b>Grade professionnel maximal atteint.</b><br>${S.masterCertified?'👑 Consécration obtenue : Maître juré des Terres.':'Le dossier de consécration est maintenant disponible dans l’onglet Maîtrise.'}</div>`}</div><div class="economy-summary"><div><span>Contrats réussis</span><b>${S.completedContracts}</b></div><div><span>Contrats échoués</span><b>${S.failedContracts}</b></div><div><span>Livraisons remarquables</span><b>${S.stats.remarkableContracts||0}</b></div><div><span>Contrats actifs</span><b>${S.activeContracts.length}/${activeContractLimit()}</b></div></div>`;
    $('#farmClients').innerHTML=`<div class="farmer-client-grid">${farmerClients().map(c=>{const unlocked=rankOrder()>=Number(c.minRank||0)&&(!c.masterOnly||S.masterCertified),trust=clientTrust(c.id);return `<article class="client-card ${unlocked?'':'locked'}"><div class="client-head"><div><span class="client-icon">${c.icon||'👤'}</span><h3>${esc(c.name)}</h3></div><span class="trust-pill">${Math.round(trust)}/100</span></div><p class="muted">${esc(c.description||'')}</p><div class="client-meta"><span>Requis : ${esc(rankName(c.minRank||0))}</span><span>${unlocked?clientStatus(trust):c.masterOnly?'🔒 Réservé aux Maîtres jurés':'🔒 Non accessible'}</span></div></article>`;}).join('')}</div>`;
    $('#farmContractOffers').innerHTML=S.contractOffers.length?S.contractOffers.map(o=>{const d=C.jobContract(o.contractId),c=C.jobClient(d?.clientId),left=Math.max(0,Math.ceil((o.expiresAt-t)/1000)),have=d?compatibleContractQty(d):0;return `<article class="contract-card offer"><div class="contract-head"><div><b>${d?.icon||'📜'} ${esc(d?.name||o.contractId)}</b><small>${esc(c?.name||'Commanditaire')} · proposition ${left}s</small></div><span class="trust-pill">Confiance ${Math.round(clientTrust(d?.clientId))}</span></div><p>${esc(d?.description||'')}</p><div class="contract-requirement"><span>${res(d?.resourceId)?.icon||'📦'} ${d?.quantity||0} × ${esc(res(d?.resourceId)?.name||d?.resourceId||'')}</span><b>Compatible ${Math.floor(have)}/${d?.quantity||0}</b></div>${hasFarmCriteria(d)?`<div class="contract-specs"><span>${esc(criteriaText(d))}</span></div>`:''}${d?.requiredLandId?'<div class="prestige-contract-note">🌟 Contrat de prestige issu d’une terre unique</div>':''}${d?.requiresMaster?'<div class="master-contract-note">👑 Mandat réservé aux Maîtres jurés</div>':''}<div class="contract-rewards"><span>XP +${d?.reward?.jobXp||0}</span><span>Réputation +${d?.reward?.reputation||0}</span><span>Village XP +${d?.reward?.villageXp||0}</span><span>🪙 ${d?.reward?.treasury||0}</span></div><div class="contract-actions"><button class="btn primary" onclick="farmerAcceptContract('${o.id}')" ${S.activeContracts.length>=activeContractLimit()?'disabled':''}>Accepter</button><button class="btn" onclick="farmerDeclineContract('${o.id}')">Refuser</button></div></article>`;}).join(''):'<div class="empty-state"><b>Aucune nouvelle proposition</b><span>Les commandes apparaissent selon ton grade, ta réputation et la confiance des commanditaires.</span></div>';
    $('#farmActiveContracts').innerHTML=S.activeContracts.length?S.activeContracts.map(a=>{const d=C.jobContract(a.contractId),c=C.jobClient(d?.clientId),left=Math.max(0,Math.ceil((a.end-t)/1000)),have=d?compatibleContractQty(d):0,pct=Math.min(100,have/Math.max(1,Number(d?.quantity||1))*100);return `<article class="contract-card active ${have>=Number(d?.quantity||1)?'ready':''}"><div class="contract-head"><div><b>${d?.icon||'📜'} ${esc(d?.name||a.contractId)}</b><small>${esc(c?.name||'Commanditaire')} · <span class="contract-timer">${left}s</span></small></div></div><div class="contract-requirement"><span>Stock compatible</span><b>${Math.floor(have)}/${d?.quantity||0}</b></div><div class="progress"><i style="width:${pct}%"></i></div>${hasFarmCriteria(d)?`<div class="contract-specs"><span>${esc(criteriaText(d))}</span></div>`:''}${d?.requiresMaster?'<div class="master-contract-note">👑 Mandat de maître</div>':''}<div class="contract-actions"><button class="btn primary" onclick="farmerDeliverContract('${a.id}')" ${have>=Number(d?.quantity||1)?'':'disabled'}>📦 Livrer</button><button class="btn danger" onclick="farmerAbandonContract('${a.id}')">Abandonner</button></div></article>`;}).join(''):'<div class="empty-state"><b>Aucun contrat actif</b><span>Accepte une proposition pour prendre un engagement agricole.</span></div>';
    $('#farmContractHistory').innerHTML=S.contractHistory.length?S.contractHistory.slice(0,18).map(h=>{const d=C.jobContract(h.contractId),ok=h.status==='delivered';return `<div class="history-row ${ok?'ok':'failed'}"><span>${ok?'✓':'✕'} ${esc(d?.name||h.contractId)}</span><b>${ok?(h.remarkable?'Livraison remarquable':'Livré'):'Échoué'}</b><small>${new Date(h.at).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})}${h.reason?` · ${esc(h.reason)}`:''}</small></div>`;}).join(''):'<p class="muted">Aucun contrat terminé pour le moment.</p>';
  }
  function conditionLabel(id){const p=toolConditionPct(id);return p<=0?'Hors service':p<30?'Très usé':p<60?'Usé':p<85?'Bon état':'Excellent état';}
  window.farmerBuyTool=id=>{const t=farmerTool(id);if(!t||ownsTool(id)||!meetsGate(t))return;const price=Number(t.price||0);if(Number(C.state.treasury||0)<price)return alert(`Il faut ${price} couronnes.`);C.state.treasury-=price;S.ownedTools.push(id);S.toolCondition[id]=toolMax(id);S.toolXp[id]=Number(S.toolXp[id]||0);if(!S.equippedTools[t.operation])S.equippedTools[t.operation]=id;S.stats.toolsBought++;C.log(`🧰 Outil Fermier acheté : ${t.name}.`);C.save();render();};
  window.farmerEquipTool=id=>{const t=farmerTool(id);if(!t||!ownsTool(id)||!meetsGate(t))return;S.equippedTools[t.operation]=id;C.log(`🧰 ${t.name} équipé pour ${t.operation}.`);C.save();render();};
  window.farmerRepairTool=id=>{const t=farmerTool(id);if(!t||!ownsTool(id)||toolCondition(id)>=toolMax(id)-.5)return;const cost=repairCost(id);if(cost<=0&&t.starter&&toolCondition(id)<=0){S.toolCondition[id]=Math.round(toolMax(id)*.25);C.log(`🔧 Remise en état de secours : ${t.name} revient à 25 %.`);}else{if(Number(C.state.treasury||0)<cost)return alert(`Il faut ${cost} couronnes.`);C.state.treasury-=cost;S.toolCondition[id]=toolMax(id);S.stats.repairs++;C.log(`🔧 ${t.name} entretenu pour ${cost} couronnes.`);}C.save();render();};
  window.farmerBuyGear=id=>{const g=farmerGear(id);if(!g||ownsGear(id)||!meetsGate(g))return;const price=Number(g.price||0);if(Number(C.state.treasury||0)<price)return alert(`Il faut ${price} couronnes.`);C.state.treasury-=price;S.ownedGear.push(id);if(!S.equippedGear[g.slot])S.equippedGear[g.slot]=id;S.stats.toolsBought++;C.log(`🎒 Équipement Fermier acheté : ${g.name}.`);C.save();render();};
  window.farmerEquipGear=id=>{const g=farmerGear(id);if(!g||!ownsGear(id)||!meetsGate(g))return;S.equippedGear[g.slot]=id;C.log(`🎒 ${g.name} équipé.`);C.save();render();};
  window.farmerSellResource=(id,all=false)=>{refreshMarket();const m=marketItem(id);if(!m||m.qualitative)return;const have=C.resource(id);if(have<=0)return;const qty=all?have:1,price=commonPrice(id),total=Math.round(price*qty*100)/100;if(!C.consumeResource(id,qty,'Vente marché Fermier'))return;C.state.treasury+=total;S.stats.marketSales+=qty;S.stats.marketRevenue+=total;S.marketDemand[id]=clamp(marketDemand(id)-qty*.006,Number(m.minDemand||.7),Number(m.maxDemand||1.35));C.log(`💰 Vente agricole : ${qty} × ${m.name} pour ${total.toFixed(2)} couronnes.`);C.save();render();};
  window.farmerSellLot=(resourceId,lotId)=>{refreshMarket();const lots=C.state.materialLots?.[resourceId]||[],l=lots.find(x=>x.id===lotId),m=marketItem(resourceId);if(!l||!m)return;const total=lotPrice(resourceId,l),qty=Number(l.quantity||0);C.state.materialLots[resourceId]=lots.filter(x=>x.id!==lotId);C.state.resources[resourceId]=Math.max(0,C.resource(resourceId)-qty);C.recordInventoryEvent('out',resourceId,qty,'Vente marché Fermier');C.state.treasury+=total;S.stats.marketSales+=qty;S.stats.marketRevenue+=total;S.marketDemand[resourceId]=clamp(marketDemand(resourceId)-qty*.008,Number(m.minDemand||.7),Number(m.maxDemand||1.35));C.log(`💰 Lot de ${m.name.toLowerCase()} vendu : ${qty} unité(s), qualité ${qlabel(l.quality)}, pour ${total} couronnes.`);C.save();render();};
  window.farmerChooseSpec=id=>{const d=specDef(id);if(!d||S.level<Number(d.minLevel||5)||rankOrder()<Number(d.minRank||2))return;if(!S.specialization.primary){S.specialization.primary=id;C.log(`🧭 Spécialisation principale Fermier : ${d.name}.`);}else if(S.specialization.primary!==id&&!S.specialization.secondary&&rankOrder()>=5&&spentInSpec(S.specialization.primary)>=4){S.specialization.secondary=id;C.log(`🧭 Spécialisation secondaire Fermier : ${d.name}.`);}C.save();render();};
  window.farmerInvestTalent=(specId,talentId)=>{const d=specDef(specId),t=d?.talents?.find(x=>x.id===talentId);if(!d||!t||!canInvestTalent(specId,t))return;S.specialization.talents[t.id]=true;C.log(`🌾 Talent Fermier acquis : ${t.name}.`);C.save();render();};
  window.farmerRespecSpec=()=>{if(!S.specialization.primary)return;const cost=20+specPointsSpent()*10;if(Number(C.state.treasury||0)<cost)return alert(`Changer de spécialisation coûte ${cost} couronnes.`);if(!confirm(`Réinitialiser les spécialisations pour ${cost} couronnes ?`))return;C.state.treasury-=cost;S.specialization={primary:'',secondary:'',talents:{}};C.log(`🧭 Spécialisations Fermier réinitialisées pour ${cost} couronnes.`);C.save();render();};
  function renderEquipment(){const treasury=Math.round(Number(C.state.treasury||0)),phaseLabels={prepare:'Préparation du sol',care:'Soins culturaux',harvest:'Récolte',sort:'Tri'},slotLabels={irrigation:'Irrigation',protection:'Protection & ergonomie',hauling:'Transport'};$('#farmerTools').innerHTML=`<div class="notice subtle">Trésorerie : <b>${treasury} 🪙</b>. L’état des outils influence énergie, rendement et qualité ; chaque outil gagne aussi sa propre maîtrise.</div><div class="equipment-grid">${tools().map(t=>{const unlocked=meetsGate(t),owned=ownsTool(t.id),equipped=S.equippedTools[t.operation]===t.id,pct=owned?Math.round(toolConditionPct(t.id)):0;return `<article class="equipment-card ${owned?'owned':''} ${equipped?'equipped':''} ${unlocked?'':'locked'}"><div class="equipment-head"><span>${t.icon||'🧰'}</span><div><b>${esc(t.name)}</b><small>${phaseLabels[t.operation]||t.operation} · ${owned?`${conditionLabel(t.id)} · maîtrise ${toolMastery(t.id)}/10`:`${t.price||0} 🪙`}</small></div></div><p class="muted">${esc(t.description||'')}</p><div class="equipment-stats"><span>Efficacité ×${Number(t.efficiency||1).toFixed(2)}</span><span>Qualité +${t.qualityBonus||0}</span><span>Durabilité ${t.maxDurability||100}</span></div>${owned?`<div class="durability-row"><span>${pct}%</span><div class="durability-meter"><i style="width:${pct}%"></i></div><b>${conditionLabel(t.id)}</b></div><div class="equipment-actions"><button class="btn primary" onclick="farmerEquipTool('${t.id}')" ${equipped||!unlocked?'disabled':''}>${equipped?'Équipé':'Équiper'}</button><button class="btn" onclick="farmerRepairTool('${t.id}')" ${pct>=99?'disabled':''}>🔧 ${repairCost(t.id)?`Entretenir · ${repairCost(t.id)} 🪙`:'Remise en état'}</button></div>`:`<div class="equipment-actions"><button class="btn primary" onclick="farmerBuyTool('${t.id}')" ${!unlocked||treasury<Number(t.price||0)?'disabled':''}>Acheter · ${t.price||0} 🪙</button></div>`}</article>`;}).join('')}</div>`;
    $('#farmerGear').innerHTML=`<div class="equipment-grid">${gearDefs().map(g=>{const unlocked=meetsGate(g),owned=ownsGear(g.id),equipped=S.equippedGear[g.slot]===g.id;return `<article class="equipment-card ${owned?'owned':''} ${equipped?'equipped':''} ${unlocked?'':'locked'}"><div class="equipment-head"><span>${g.icon||'🎒'}</span><div><b>${esc(g.name)}</b><small>${slotLabels[g.slot]||g.slot}${equipped?' · équipé':''}</small></div></div><p class="muted">${esc(g.description||'')}</p><div class="equipment-stats">${Object.entries(g.effects||{}).map(([k,v])=>`<span>${esc(k)} ${Number(v)>=0?'+':''}${v}</span>`).join('')}</div><div class="equipment-actions">${owned?`<button class="btn primary" onclick="farmerEquipGear('${g.id}')" ${equipped||!unlocked?'disabled':''}>${equipped?'Équipé':'Équiper'}</button>`:`<button class="btn primary" onclick="farmerBuyGear('${g.id}')" ${!unlocked||treasury<Number(g.price||0)?'disabled':''}>Acheter · ${g.price||0} 🪙</button>`}</div></article>`;}).join('')}</div>`;}
  function renderEconomy(){refreshMarket();const left=Math.max(0,Math.ceil((180000-(now()-S.lastMarketTick))/1000));$('#farmMarket').innerHTML=`<div class="notice subtle">La demande locale est réévaluée dans ≈ <b>${left}s</b>. Les récoltes traçables sont valorisées selon leur <b>qualité</b> et leur <b>fraîcheur</b>.</div><div class="market-list">${marketDefs().map(m=>{const d=marketDemand(m.id),stock=C.resource(m.id);return `<div class="market-row"><div><b>${esc(m.name)}${m.transformed?' · ⚙️ transformé':''}</b><small>${esc(m.description||'')}</small><span class="demand-badge ${demandClass(d)}">Demande ${demandLabel(d)} · ×${d.toFixed(2)}</span></div><strong>${m.qualitative?'par lot':`${commonPrice(m.id).toFixed(2)} 🪙 / unité`}</strong>${m.qualitative?`<span>${(C.state.materialLots[m.id]||[]).reduce((a,l)=>a+Number(l.quantity||0),0)} unité(s) traçable(s)</span>`:`<div class="market-actions"><button class="btn" onclick="farmerSellResource('${m.id}',false)" ${stock<1?'disabled':''}>Vendre 1</button><button class="btn" onclick="farmerSellResource('${m.id}',true)" ${stock<1?'disabled':''}>Tout vendre (${stock})</button></div>`}</div>`;}).join('')}</div>`;
    const lots=marketDefs().filter(m=>m.qualitative).flatMap(m=>(C.state.materialLots[m.id]||[]).map(l=>({rid:m.id,l})));$('#farmMarketLots').innerHTML=lots.length?`<div class="wood-market-grid">${lots.map(({rid,l})=>{const m=marketItem(rid),price=lotPrice(rid,l),fresh=Math.round(freshness(l)*100);return `<article class="wood-market-lot"><div class="wood-market-lot-head"><div><b>${res(rid)?.icon||'🌾'} ${esc(m?.name||rid)}</b><small>${l.quantity} unité(s) · ${qlabel(l.quality)} · fraîcheur ${fresh}%</small></div><strong>Q ${Math.round(l.quality||0)}</strong></div><div class="wood-market-meta"><span>${esc(l.soilName||soil(l.soilId)?.name||(l.sourceSoilIds?.length>1?'Assemblage de terroirs':l.soilId)||'origine non tracée')}</span><span>${l.processedRecipeId?'⚙️ Produit transformé':`Parcelle ${l.plotNo||'—'}`}</span><span>Demande ×${marketDemand(rid).toFixed(2)}</span></div><div class="wood-market-price"><span>Valeur actuelle</span><strong>${price} 🪙</strong></div><button class="btn primary" onclick="farmerSellLot('${rid}','${l.id}')">Vendre le lot</button></article>`;}).join('')}</div>`:'<div class="empty-state"><b>Aucun lot agricole traçable</b><span>Récolte, trie puis stocke une production active pour accéder au marché qualitatif.</span></div>';
    $('#farmEconomySummary').innerHTML=`<div class="economy-summary"><div><span>Trésorerie</span><b>${Math.round(Number(C.state.treasury||0))} 🪙</b></div><div><span>Revenus agricoles</span><b>${Math.round(S.stats.marketRevenue||0)} 🪙</b></div><div><span>Unités vendues</span><b>${Math.round(S.stats.marketSales||0)}</b></div><div><span>Contrats réussis</span><b>${S.completedContracts}</b></div></div>`;}
  function renderSpecializations(){const total=specPointTotal(),free=specPointsFree(),eligible=rankOrder()>=2&&S.level>=5,canSecondary=rankOrder()>=5&&S.specialization.primary&&spentInSpec(S.specialization.primary)>=4;$('#farmerSpecializations').innerHTML=`<div class="spec-summary"><div><span>Orientation actuelle</span><b>${S.specialization.primary?esc(specDef(S.specialization.primary)?.name||'—'):'Aucune spécialisation'}${S.specialization.secondary?` + ${esc(specDef(S.specialization.secondary)?.name||'')}`:''}</b></div><div><span>Points de spécialisation</span><b>${free} disponible(s) / ${total}</b></div>${S.specialization.primary?`<button class="btn" onclick="farmerRespecSpec()">Réorienter · ${20+specPointsSpent()*10} 🪙</button>`:''}</div>${!eligible?'<div class="notice subtle">Les spécialisations se débloquent au niveau 5 et au grade Cultivateur confirmé.</div>':''}<div class="spec-grid">${specDefs().map(d=>{const active=activeSpec(d.id),isPrimary=S.specialization.primary===d.id,isSecondary=S.specialization.secondary===d.id,branchUnlocked=eligible&&(!S.specialization.primary||active||(canSecondary&&!S.specialization.secondary));return `<article class="spec-card ${isPrimary?'primary':''} ${isSecondary?'secondary':''} ${branchUnlocked||active?'':'locked'}"><div class="spec-title"><span>${d.icon||'🌾'}</span><div><b>${esc(d.name)}</b><small>${isPrimary?'Spécialisation principale':isSecondary?'Spécialisation secondaire':esc(d.description||'')}</small></div></div><p class="muted">${esc(d.description||'')}</p>${!active?`<button class="btn primary" onclick="farmerChooseSpec('${d.id}')" ${!branchUnlocked?'disabled':''}>${!S.specialization.primary?'Choisir cette voie':canSecondary&&!S.specialization.secondary?'Choisir en secondaire':'Voie inactive'}</button>`:''}<div class="talent-list">${(d.talents||[]).map(t=>{const got=hasTalent(t.id),can=canInvestTalent(d.id,t),req=(t.requires||[]).map(rid=>d.talents.find(x=>x.id===rid)?.name||rid).join(', ');return `<div class="talent ${got?'unlocked':active?'':'locked'}"><div class="talent-head"><b>${got?'✓ ':''}${esc(t.name)}</b><span>${t.cost||1} pt</span></div><p>${esc(t.description||'')}${!got&&req?` · Requis : ${esc(req)}`:''}</p>${active&&!got?`<button class="btn" onclick="farmerInvestTalent('${d.id}','${t.id}')" ${can?'':'disabled'}>Débloquer</button>`:''}</div>`;}).join('')}</div></article>`;}).join('')}</div>${S.specialization.primary&&!canSecondary?'<div class="notice subtle" style="margin-top:12px">Une spécialisation secondaire sera accessible au grade Maître des terres après 4 talents investis dans la voie principale.</div>':''}`;}
  function renderEvents(){eventTick();cleanEventModifiers();const life=eventLife(),cfg=eventConfig(),pending=life.pending,def=farmEvent(pending?.eventId),cal=calendarState();const current=$('#farmEventCurrent');if(current){if(def&&pending){const category=EVENT_CATEGORIES[def.category]||['Événement','🌾'];current.innerHTML=`<article class="farm-event-focus ${esc(def.tone||'mixed')}"><div class="farm-event-focus-head"><span>${def.icon||category[1]}</span><div><small>${category[1]} ${esc(category[0])} · ${season(pending.seasonId)?.name||cal.season?.name||'saison'} · année ${pending.year||cal.year}</small><h3>${esc(def.name)}</h3><p>${esc(def.description||'')}</p></div></div><div class="farm-event-choice-grid">${(def.choices||[]).map(choice=>{const st=eventChoiceStatus(choice);return `<article class="farm-event-choice ${st.ok?'available':'blocked'}"><div><b>${esc(choice.label)}</b><p>${esc(choice.description||'')}</p><small>${esc(eventCostText(choice))}</small>${!st.ok?`<em>Manque : ${esc(st.reasons.join(' · '))}</em>`:''}</div><button class="btn ${st.ok?'primary':''}" onclick="farmerResolveEvent('${choice.id}')" ${st.ok?'':'disabled'}>Choisir</button></article>`}).join('')}</div><div class="notice subtle"><b>Principe :</b> cet événement reste en attente jusqu’à ta décision. Aucun autre événement ne s’empile et l’absence de réponse n’applique pas automatiquement la pire conséquence.</div></article>`;}else current.innerHTML=`<div class="empty-state"><b>🌾 Aucun événement en attente</b><span>L’exploitation suit son cours. Les situations apparaissent au changement de journée agricole, selon la saison, ton niveau et l’état des parcelles.</span><small>Chance de base : ${Math.round(Number(cfg.chancePerDay||0)*100)}% par jour admissible · intervalle minimum ${cfg.minGapDays||2} jours.</small></div>`;}
    const mods=activeEventModifiers(),modHost=$('#farmEventModifiers');if(modHost)modHost.innerHTML=mods.length?`<div class="farm-event-mod-list">${mods.map(m=>{const d=farmEvent(m.eventId);return `<article><span>${d?.icon||'🌾'}</span><div><b>${esc(d?.name||'Effet agricole')}</b><small>${esc(modifierDescription(m))}</small><em>Encore ${C.autonomyFormatDuration(Math.max(0,Number(m.endsAt||0)-now()))}</em></div></article>`}).join('')}</div>`:'<div class="empty-state compact"><b>Aucun effet temporaire</b><span>Les parcelles ne subissent actuellement aucun modificateur d’événement.</span></div>';
    const sum=$('#farmEventSummary');if(sum)sum.innerHTML=`<div class="economy-summary"><div><span>Événements rencontrés</span><b>${S.stats.eventsTriggered||0}</b></div><div><span>Décisions prises</span><b>${S.stats.eventsResolved||0}</b></div><div><span>Crises gérées</span><b>${S.stats.eventCrisesHandled||0}</b></div><div><span>Opportunités</span><b>${S.stats.eventOpportunities||0}</b></div><div><span>Vie communautaire</span><b>${S.stats.eventCommunity||0}</b></div><div><span>Découvertes</span><b>${S.stats.eventDiscoveries||0}</b></div></div><div class="notice subtle"><b>Équilibre :</b> les événements défavorables proposent toujours au moins une réponse active ou une option sans dépense. Les événements positifs ne sont pas garantis et les situations exigeant des cultures n’apparaissent que si une parcelle est réellement en production.</div>`;
    const hist=$('#farmEventHistory');if(hist)hist.innerHTML=life.history.length?`<div class="farm-event-history">${life.history.slice(0,24).map(h=>{const d=farmEvent(h.eventId),choice=d?.choices?.find(c=>c.id===h.choiceId),cat=EVENT_CATEGORIES[d?.category]||['Événement','🌾'];return `<div class="farm-event-history-row"><span>${d?.icon||cat[1]}</span><div><b>${esc(d?.name||h.eventId)}</b><small>${esc(choice?.label||h.choiceId)} · ${season(h.seasonId)?.name||'saison'} · année ${h.year||1}${h.affectedPlots?` · ${h.affectedPlots} parcelle(s)`:''}</small></div><em>${new Date(h.at).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})}</em></div>`}).join('')}</div>`:'<div class="empty-state compact"><b>Aucune chronique encore</b><span>Les décisions agricoles prises apparaîtront ici.</span></div>';
    const catHost=$('#farmEventCatalog');if(catHost)catHost.innerHTML=`<div class="farm-event-catalog">${eventDefs().map(d=>{const levelOk=S.level>=Number(d.minLevel||1)&&C.buildingLevel('farm')>=Number(d.minFarmLevel||1),onceDone=d.once&&life.resolvedOnce.includes(d.id),cat=EVENT_CATEGORIES[d.category]||['Événement','🌾'],seasonNames=(d.seasons||[]).map(id=>season(id)?.name||id).join(', ');return `<article class="${levelOk?'':'locked'} ${onceDone?'resolved-once':''}"><span>${d.icon||cat[1]}</span><div><b>${esc(d.name)}</b><small>${cat[1]} ${esc(cat[0])} · niv. ${d.minLevel||1}${d.minFarmLevel>1?` · Ferme ${d.minFarmLevel}`:''}</small><p>${esc(d.description||'')}</p><em>${onceDone?'✓ Événement unique déjà vécu':levelOk?`Saisons : ${esc(seasonNames||'toutes')}${d.requiresGrowing?' · culture active requise':''}`:`🔒 Niveau ou Ferme insuffisant`}</em></div></article>`}).join('')}</div>`;
    const badge=$('#farmEventNavBadge'),tab=document.querySelector('[data-tab="events"]');if(badge)badge.classList.toggle('hidden',!life.pending);if(tab)tab.classList.toggle('event-pending',!!life.pending);}
  function renderFood(){C.processFoodSecurity?.();const st=C.foodSecurityStatus?.()||{id:'inactive',label:'Non activée',icon:'🌾',score:0,days:0,normalDays:0,workModifier:1,grace:0},f=C.foodState?.()||{},cfg=C.foodConfig?.()||{},comp=C.foodReserveComposition?.()||[],target=C.foodTargetDays?.()||10,need=C.foodDailyNeed?.()||0,baseNeed=C.foodBaseDailyNeed?.()||0,groups=C.foodVarietyGroups?.()||[],policy=C.foodPolicy?.()||{id:'normal',name:'Ration normale',icon:'🍲'},pres=Math.round(Number(C.buildingEffect('warehouse','foodPreservation',1)||1)*100),reservePct=Math.min(100,(Number(st.normalDays||0)/Math.max(1,target))*100);const summary=$('#farmFoodSummary');if(summary)summary.innerHTML=`<div class="food-security-hero ${st.id}"><div class="food-security-score"><span>${st.icon||'🍲'}</span><div><small>Sécurité alimentaire</small><b>${esc(st.label||'—')}</b><em>${Math.round(Number(st.score||0))}/100</em></div></div><div class="food-security-main"><div><span>Autonomie actuelle</span><b>${Number(st.days||0).toFixed(1)} j</b><small>${Number(st.normalDays||0).toFixed(1)} j à ration normale</small></div><div><span>Objectif du grenier</span><b>${target} j</b><small>Réglage ${Math.max(2,target-Number(C.buildingEffect('farm','foodReserveTargetBonus',0)||0))} + bonus Ferme ${Number(C.buildingEffect('farm','foodReserveTargetBonus',0)||0)}</small></div><div><span>Besoin / jour</span><b>${need.toFixed(2)} rations</b><small>${C.state.population} habitant(s) · normal ${baseNeed.toFixed(2)}</small></div><div><span>Efficacité du travail</span><b>×${Number(st.workModifier||1).toFixed(2)}</b><small>Politique : ${esc(policy.name||'—')}</small></div></div><div class="progress food-reserve-progress"><i style="width:${reservePct}%"></i></div><p>${esc(st.description||'')}</p>${Number(st.grace||0)>0?`<div class="notice subtle">🌱 <b>Période de mise en réserve :</b> encore ${Math.round(st.grace)} journée(s) avant la consommation régulière. Profite-en pour constituer un stock initial.</div>`:''}</div><div class="food-target-controls"><span>Objectif de réserve</span><button class="btn" data-food-target="-1">− 1 jour</button><b>${target} jours</b><button class="btn" data-food-target="1">+ 1 jour</button></div>`;
    const composition=$('#farmFoodComposition');if(composition)composition.innerHTML=comp.length?`<div class="food-stock-list">${comp.map(r=>{const contribution=baseNeed>0?r.units/baseNeed:0,loss=Number(r.spoilagePerDay||0)*Number(C.buildingEffect('warehouse','foodPreservation',1)||1)*100;return `<div class="food-stock-row ${r.quantity>.01?'has-stock':'empty'}"><span>${r.icon}</span><div><b>${esc(r.name)}</b><small>${esc(r.group)} · ${Number(r.foodValue).toFixed(2)} ration/u. · pertes ~${loss.toFixed(1)}%/j</small></div><strong>${Number(r.quantity).toFixed(r.quantity<10?1:0)}</strong><em>${contribution.toFixed(1)} j</em></div>`}).join('')}</div><div class="notice subtle">🏺 Conservation Entrepôt : <b>${pres}% du taux de perte de base</b>. Améliorer l’Entrepôt réduit les pertes, surtout sur les légumes frais.</div>`:'<div class="empty-state"><b>Aucun aliment reconnu</b><span>Les récoltes agricoles stockées apparaîtront ici.</span></div>';
    const policies=$('#farmFoodPolicies');if(policies)policies.innerHTML=`<div class="food-policy-grid">${(cfg.policies||[]).map(p=>`<article class="food-policy-card ${p.id===f.policy?'active':''}"><div><span>${p.icon||'🍲'}</span><b>${esc(p.name)}</b></div><p>${esc(p.description||'')}</p><small>Consommation ×${Number(p.consumptionFactor||1).toFixed(2)} · travail ×${Number(p.workModifier||1).toFixed(2)}</small><button class="btn ${p.id===f.policy?'':'primary'}" data-food-policy="${p.id}" ${p.id===f.policy?'disabled':''}>${p.id===f.policy?'Politique active':'Adopter'}</button></article>`).join('')}</div><div class="notice subtle"><b>Variété actuelle :</b> ${groups.length?groups.map(x=>esc(x)).join(' · '):'aucune famille alimentaire en stock'}. Une réserve variée améliore le score de sécurité alimentaire.</div>`;
    const seeds=$('#farmSeedReserve');if(seeds){const defs=C.seedResources?.()||[];seeds.innerHTML=`<div class="seed-reserve-list">${defs.map(r=>{const stock=C.resource(r.id),protectedQty=C.seedReserveTarget?.(r.id)||0,usable=C.seedUsable?.(r.id)??stock,ready=stock+1e-9>=protectedQty;return `<div class="seed-reserve-row ${ready?'ready':'missing'}"><span>${r.icon||'🌱'}</span><div><b>${esc(r.name)}</b><small>Stock total ${Number(stock).toFixed(stock<10?1:0)} · utilisable ${Number(usable).toFixed(usable<10?1:0)}</small></div><div class="seed-reserve-controls"><button class="tiny-action" data-seed-target="${r.id}|-1">−</button><strong>Protégé ${protectedQty}</strong><button class="tiny-action" data-seed-target="${r.id}|1">+</button></div></div>`}).join('')}</div><div class="notice subtle"><b>Protection des semences :</b> le Fermier refusera automatiquement un semis qui ferait passer le stock sous le seuil protégé. Ce seuil peut être abaissé volontairement ici.</div>`;}
    const hist=$('#farmFoodHistory');if(hist){const rows=Array.isArray(f.history)?f.history.slice(0,18):[];hist.innerHTML=rows.length?`<div class="food-history-list">${rows.map(h=>`<div class="food-history-row ${h.grace?'grace':Number(h.missing||0)>.01?'shortage':'ok'}"><span>${h.grace?'🌱':Number(h.missing||0)>.01?'🔴':'✓'} Jour ${h.day}</span><b>${h.grace?'Mise en réserve':`${Number(h.fed||0).toFixed(2)}/${Number(h.need||0).toFixed(2)} ration(s)`}</b><small>${h.grace?'Aucune consommation pendant la période de grâce':`Pertes ${Number(h.spoiledQty||0).toFixed(2)} u. · réserve restante ${Number(h.reserveDays||0).toFixed(1)} j · pop. ${h.population}`}</small></div>`).join('')}</div>`:'<div class="empty-state compact"><b>Aucune journée alimentaire écoulée</b><span>Une journée agricole dure environ ${Math.round(Number(cfg.dayMs||18000)/1000)} secondes dans ce prototype.</span></div>';}
    document.querySelectorAll('[data-food-policy]').forEach(b=>b.onclick=()=>{C.setFoodPolicy?.(b.dataset.foodPolicy);renderFood();renderTop();});document.querySelectorAll('[data-food-target]').forEach(b=>b.onclick=()=>{const cur=Math.max(2,Number(f.targetDays||cfg.defaultTargetDays||10));C.setFoodTargetDays?.(cur+Number(b.dataset.foodTarget||0));renderFood();});document.querySelectorAll('[data-seed-target]').forEach(b=>b.onclick=()=>{const [id,delta]=b.dataset.seedTarget.split('|'),cur=C.seedReserveTarget?.(id)||0;C.setSeedReserveTarget?.(id,cur+Number(delta||0));renderFood();renderPlots();});}
  function renderProgression(){updateAll();const cropMastered=crops().filter(c=>knowledgeLevel(c.id)>=3).length,soilMastered=soils().filter(sd=>knowledgeLevel(sd.id,true)>=3).length;$('#farmProgression').innerHTML=`<div class="economy-summary"><div><span>Parcelles préparées</span><b>${S.stats.plotsPrepared}</b></div><div><span>Semis</span><b>${S.stats.sowings}</b></div><div><span>Soins</span><b>${S.stats.careActions}</b></div><div><span>Récoltes</span><b>${S.stats.harvests}</b></div><div><span>Lots triés</span><b>${S.stats.sorted}</b></div><div><span>Unités stockées</span><b>${S.stats.stored}</b></div><div><span>Puzzles réussis</span><b>${S.stats.puzzlesWon}/${S.stats.puzzles}</b></div><div><span>Gestes utilisés</span><b>${S.stats.gesturesUsed}</b></div><div><span>Cultures maîtrisées</span><b>${cropMastered}/${crops().length}</b></div><div><span>Sols maîtrisés</span><b>${soilMastered}/${soils().length}</b></div><div><span>Bonnes rotations</span><b>${S.stats.rotationsGood||0}</b></div><div><span>Monocultures pénalisées</span><b>${S.stats.rotationsPoor||0}</b></div><div><span>Maladies observées</span><b>${S.stats.diseaseEvents||0}</b></div><div><span>Ravageurs observés</span><b>${S.stats.pestEvents||0}</b></div><div><span>Menaces traitées</span><b>${S.stats.threatsTreated||0}</b></div><div><span>Science du sol</span><b>${skillLevel('soil')}/10</b></div><div><span>Conduite culturale</span><b>${skillLevel('cultivation')}/10</b></div><div><span>Récolte & tri</span><b>${skillLevel('harvest')}/10</b></div><div><span>Transformation agricole</span><b>${window.VillageFarmerProcessing?.skillLevel?.()||1}/10</b></div><div><span>Lots transformés</span><b>${S.stats.processingBatches||0}</b></div><div><span>Unités transformées</span><b>${Math.round(S.stats.processedUnits||0)}</b></div><div><span>Meilleure qualité</span><b>${S.stats.bestQuality?`${qlabel(S.stats.bestQuality)} · ${S.stats.bestQuality}/100`:'—'}</b></div><div><span>Qualité ≥ Sélectionnée</span><b>${Math.round(S.stats.highQualityUnits||0)}</b></div><div><span>Qualité ≥ Excellente</span><b>${Math.round(S.stats.excellentUnits||0)}</b></div><div><span>Contrats réussis</span><b>${S.completedContracts}</b></div><div><span>Contrats de prestige</span><b>${S.stats.prestigeContracts||0}</b></div><div><span>Recommandations</span><b>${S.endorsements.length}</b></div><div><span>Sceaux de maîtrise</span><b>${S.masterySeals.length}/${sealDefs().length}</b></div><div><span>Réputation</span><b>${Math.round(S.reputation)}/100</b></div><div><span>Outils achetés</span><b>${S.stats.toolsBought||0}</b></div><div><span>Entretiens</span><b>${S.stats.repairs||0}</b></div><div><span>Revenus marché</span><b>${Math.round(S.stats.marketRevenue||0)} 🪙</b></div><div><span>Terres uniques</span><b>${S.stats.uniqueLandsDiscovered||0}/${uniqueLands().length}</b></div><div><span>Récoltes rares</span><b>${S.stats.rareHarvests||0}</b></div><div><span>Récoltes de prestige</span><b>${S.stats.prestigeHarvests||0}</b></div><div><span>Jours nourris sans pénurie</span><b>${C.foodState?.().stats?.secureDays||0}</b></div><div><span>Jours de pénurie</span><b>${C.foodState?.().stats?.shortageDays||0}</b></div><div><span>Événements rencontrés</span><b>${S.stats.eventsTriggered||0}</b></div><div><span>Décisions agricoles</span><b>${S.stats.eventsResolved||0}</b></div><div><span>Crises gérées</span><b>${S.stats.eventCrisesHandled||0}</b></div><div><span>Opportunités saisies</span><b>${S.stats.eventOpportunities||0}</b></div><div><span>Spécialisation</span><b>${S.specialization.primary?esc(specDef(S.specialization.primary)?.name||'—'):'—'}</b></div></div><div class="notice subtle"><b>VIL0.3.13.9 :</b> le grand audit ferme la carrière du Fermier : renommée, recommandations, quatre sceaux et consécration de Maître juré des Terres complètent désormais toute la progression.</div>`;}
  function rewardCareer(r={}){if(r.jobXp)C.gainJobXp('farmer',Number(r.jobXp));if(r.villageXp)C.gainVillageXp(Number(r.villageXp));if(r.reputation)S.reputation=clampRep(S.reputation+Number(r.reputation));if(r.treasury)C.state.treasury=Math.max(0,Number(C.state.treasury||0)+Number(r.treasury));if(r.masteryXp)C.gainMastery('farmer',Number(r.masteryXp));}
  function sealRequirementRows(seal){const req=seal?.requirements||{},rows=[],add=(label,have,need,displayHave,displayNeed)=>rows.push({label,have:Number(have||0),need:Number(need||0),displayHave,displayNeed,ok:Number(have||0)>=Number(need||0)});add('Niveau du métier',S.level,seal?.minLevel||1);add('Grade professionnel',rankOrder(),seal?.minRank||0,C.jobRank('farmer'),C.professionalRanks('farmer').find(r=>Number(r.order||0)===Number(seal?.minRank||0))?.name||seal?.minRank||0);const labels={harvests:'Récoltes terminées',puzzlesWon:'Puzzles réussis',highQualityUnits:'Unités qualité ≥ Sélectionnée',excellentUnits:'Unités qualité ≥ Excellente',rotationsGood:'Bonnes rotations',uniqueLandsDiscovered:'Terres uniques reconnues',rareHarvests:'Récoltes rares',prestigeHarvests:'Récoltes de prestige',processingBatches:'Lots transformés',processedUnits:'Unités transformées',bestProcessingQuality:'Meilleure qualité transformée',contractsCompleted:'Contrats réussis',prestigeContracts:'Contrats de prestige',remarkableContracts:'Livraisons remarquables',reputation:'Réputation métier',endorsements:'Recommandations reçues',eventsResolved:'Décisions agricoles'};for(const [key,label] of Object.entries(labels)){if(!Number(req[key]||0))continue;let have=key==='contractsCompleted'?S.completedContracts:key==='reputation'?S.reputation:key==='endorsements'?S.endorsements.length:Number(S.stats[key]||0);add(label,have,req[key]);}if(Number(req.knowledgeCount||0)>0){const lvl=Number(req.knowledgeLevel||1),count=crops().filter(c=>knowledgeLevel(c.id)>=lvl).length+soils().filter(sd=>knowledgeLevel(sd.id,true)>=lvl).length;add(`Cultures & sols ${K_NAMES[lvl]||'connus'}`,count,req.knowledgeCount);}for(const [toolId,need] of Object.entries(req.toolMastery||{}))add(`Maîtrise ${farmerTool(toolId)?.name||toolId}`,toolMastery(toolId),need);return rows;}
  function sealReady(seal){return !!seal&&!sealUnlocked(seal.id)&&sealRequirementRows(seal).every(r=>r.ok);}
  function masterRequirementRows(){const c=masterCareer();if(!c)return[];const rows=[],add=(label,have,need,displayHave,displayNeed)=>rows.push({label,have:Number(have||0),need:Number(need||0),displayHave,displayNeed,ok:Number(have||0)>=Number(need||0)});add('Niveau du village',C.state.level,c.minVillageLevel||6);add('Niveau du métier',S.level,c.minLevel||15);add('Grade professionnel',rankOrder(),c.minRank||5,C.jobRank('farmer'),C.professionalRanks('farmer').find(r=>Number(r.order||0)===Number(c.minRank||5))?.name||c.minRank||5);add('Réputation métier',S.reputation,c.minReputation||0);add('Sceaux de maîtrise',S.masterySeals.length,c.minSeals||0);add('Recommandations de commanditaires',S.endorsements.length,c.minEndorsements||0);add('Terres uniques reconnues',S.knownUniqueLands.length,c.minSites||0);add('Récoltes de prestige',S.stats.prestigeHarvests||0,c.minPrestigeHarvests||0);add('Contrats de prestige réussis',S.stats.prestigeContracts||0,c.minPrestigeContracts||0);add('Décisions agricoles',S.stats.eventsResolved||0,c.minEventsResolved||0);if(c.requirePrimaryCapstone)rows.push({label:'Voie principale maîtrisée',have:primaryCapstoneDone()?1:0,need:1,displayHave:primaryCapstoneDone()?`${specDef(S.specialization.primary)?.name||'Voie'} maîtrisée`:'Capstone manquante',displayNeed:'1 voie',ok:primaryCapstoneDone()});if(c.requiredContract)rows.push({label:`Chef-d’œuvre : ${C.jobContract(c.requiredContract)?.name||c.requiredContract}`,have:completedContract(c.requiredContract)?1:0,need:1,displayHave:completedContract(c.requiredContract)?'Réalisé':'Non réalisé',displayNeed:'Réalisé',ok:completedContract(c.requiredContract)});return rows;}
  window.farmerClaimSeal=id=>{const seal=C.farmerMasterySeal?C.farmerMasterySeal(id):sealDefs().find(x=>x.id===id);if(!seal||!sealReady(seal))return;S.masterySeals.push(seal.id);rewardCareer(seal.reward||{});C.log(`🏅 Sceau de maîtrise Fermier obtenu : ${seal.name}.`);C.save();render();};
  window.farmerClaimMasterTitle=()=>{const c=masterCareer(),rows=masterRequirementRows();if(!c||S.masterCertified||!rows.every(r=>r.ok))return;S.masterCertified=true;S.masterCertifiedAt=Date.now();rewardCareer(c.reward||{});const council=C.jobClient('farm_masters_council');if(council)S.clientTrust.farm_masters_council=Math.max(clientTrust('farm_masters_council'),Number(council.initialTrust||25));C.log(`👑 Consécration professionnelle : le Fermier devient ${c.name}. Les mandats du Conseil des maîtres des terres sont désormais ouverts.`);S.lastContractRefresh=0;C.evaluateAchievements?.();C.save();render();};
  function effectLabels(e={}){const out=[];const pct=(key,label)=>{if(Number(e[key]||0))out.push(`${label} +${Math.round(Number(e[key])*100)} %`);};pct('marketBonus','Prix de vente');pct('contractReward','Prime contrats');pct('trustGain','Confiance gagnée');if(Number(e.repairDiscount||0))out.push(`Entretien -${Math.round(Number(e.repairDiscount)*100)} %`);if(Number(e.activeContractSlots||0))out.push(`+${Math.round(Number(e.activeContractSlots))} contrat(s) actif(s)`);return out;}
  function renderMasterCareer(){const tier=reputationTier(),next=nextReputationTier(),tiers=reputationTiers(),seals=sealDefs(),career=masterCareer(),masterRows=masterRequirementRows(),rep=Math.round(S.reputation),nextMin=next?Number(next.minReputation||100):100,prevMin=Number(tier?.minReputation||0),pct=next?clamp((rep-prevMin)/Math.max(1,nextMin-prevMin)*100):100;$('#farmRenown').innerHTML=`<div class="renown-hero"><div><span>${tier?.icon||'🌾'}</span><div><small>Renommée professionnelle</small><b>${esc(tier?.name||'—')}</b><p>${esc(tier?.description||'')}</p></div></div><strong>${rep}/100</strong></div><div class="renown-track"><div class="progress"><i style="width:${pct}%"></i></div><small>${next?`Prochain palier : ${esc(next.name)} à ${nextMin}`:'Palier de réputation maximal atteint'}</small></div><div class="career-perks">${effectLabels(tier?.effects||{}).map(x=>`<span>${esc(x)}</span>`).join('')||'<span>Aucun avantage de renommée pour le moment</span>'}</div><div class="renown-tier-list">${tiers.map(t=>`<div class="renown-tier ${rep>=Number(t.minReputation||0)?'reached':''}"><span>${t.icon||'•'} ${esc(t.name)}</span><b>${t.minReputation}+</b></div>`).join('')}</div>`;$('#farmMasterySeals').innerHTML=`<div class="master-seal-grid">${seals.map(seal=>{const got=sealUnlocked(seal.id),rows=sealRequirementRows(seal),ready=sealReady(seal);return `<article class="master-seal ${got?'claimed':ready?'ready':''}"><div class="master-seal-head"><span>${seal.icon||'🏅'}</span><div><b>${esc(seal.name)}</b><small>${got?'Sceau obtenu':ready?'Validation disponible':'Dossier en cours'}</small></div></div><p>${esc(seal.description||'')}</p><div class="master-reqs">${rows.map(r=>`<div class="master-req ${r.ok?'ok':'missing'}"><span>${r.ok?'✓':'○'} ${esc(r.label)}</span><b>${r.displayHave?esc(r.displayHave):Math.round(r.have)} / ${r.displayNeed?esc(r.displayNeed):r.need}</b></div>`).join('')}</div><div class="career-perks">${effectLabels(seal.effects||{}).map(x=>`<span>${esc(x)}</span>`).join('')}</div>${got?'<div class="seal-stamp">✓ Validé</div>':`<button class="btn primary" onclick="farmerClaimSeal('${seal.id}')" ${ready?'':'disabled'}>🏅 Faire valider ce sceau</button>`}</article>`;}).join('')}</div>`;const endorsementClients=farmerClients().filter(c=>!c.masterOnly);$('#farmEndorsements').innerHTML=`<div class="notice subtle">À partir du grade Fermier expert et de 55 réputation, les commanditaires qui te font suffisamment confiance peuvent signer ton dossier de maîtrise.</div><div class="endorsement-list">${endorsementClients.map(c=>{const got=hasEndorsement(c.id),need=endorsementThreshold(c),trust=clientTrust(c.id),ready=canRequestEndorsement(c);return `<div class="endorsement-card ${got?'signed':''}"><span>${c.icon||'👤'}</span><div><b>${esc(c.name)}</b><small>${got?'Recommandation signée':`Confiance ${Math.round(trust)}/${need}`}</small></div>${got?'<strong>✓</strong>':`<button class="btn" onclick="farmerRequestEndorsement('${c.id}')" ${ready?'':'disabled'}>Demander</button>`}</div>`;}).join('')}</div>`;$('#farmMasterCareer').innerHTML=career?`<div class="master-charter ${S.masterCertified?'certified':''}"><div class="master-charter-head"><span>${career.icon||'👑'}</span><div><small>${S.masterCertified?'Titre professionnel obtenu':'Dossier de maîtrise final'}</small><h3>${esc(career.name)}</h3></div></div><p>${esc(career.description||'')}</p><div class="master-reqs">${masterRows.map(r=>`<div class="master-req ${r.ok?'ok':'missing'}"><span>${r.ok?'✓':'○'} ${esc(r.label)}</span><b>${r.displayHave?esc(r.displayHave):Math.round(r.have)} / ${r.displayNeed?esc(r.displayNeed):r.need}</b></div>`).join('')}</div>${S.masterCertified?`<div class="master-certified-banner">👑 Maître juré depuis le ${new Date(S.masterCertifiedAt).toLocaleDateString('fr-FR')} · ${esc(specDef(S.specialization.primary)?.name||'Fermier')}</div><div class="career-perks">${effectLabels(career.effects||{}).map(x=>`<span>${esc(x)}</span>`).join('')}</div><div class="notice subtle"><b>Conseil des maîtres des terres :</b> les contrats marqués Maître peuvent maintenant apparaître dans les propositions.</div>`:`<button class="btn primary master-claim" onclick="farmerClaimMasterTitle()" ${masterRows.every(r=>r.ok)?'':'disabled'}>👑 Soumettre le dossier au Conseil des terres</button>`}</div>`:'<p class="muted">Aucun parcours de maître configuré.</p>';}
  function renderTop(){updateAll();const cap=C.jobLevelCap('farmer'),per=Number(C.job('farmer')?.xpPerLevel||66),need=per*S.level,pct=Math.min(100,S.xp/Math.max(1,need)*100),active=F.plots.filter(p=>['growing','mature'].includes(p.status)).length,cal=calendarState(),w=currentWeather();$('#farmerRank').textContent=S.masterCertified?'Maître juré':C.jobRank('farmer');$('#farmerXpText').textContent=`Niv. ${S.level} · ${Math.floor(S.xp)} / ${need}${C.jobHasPendingLevel('farmer')?' · XP en attente':''}`;$('#farmerXpFill').style.width=`${pct}%`;$('#farmerEnergy').textContent=`${Math.floor(F.energy)} / 100`;$('#farmerEnergyFill').style.width=`${F.energy}%`;const regularCount=F.plots.filter(p=>!isUniquePlot(p)).length,uniqueCount=F.plots.filter(isUniquePlot).length;$('#farmerPlots').textContent=`${regularCount} / ${plotSlots()}${uniqueCount?` + ${uniqueCount} unique${uniqueCount>1?'s':''}`:''}`;$('#farmerActive').textContent=active;$('#farmerHarvests').textContent=S.stats.harvests;const fr=$('#farmerReputation');if(fr)fr.textContent=`${Math.round(S.reputation)} / 100 · ${reputationTier()?.name||'—'}`;const fs=$('#farmerSeason');if(fs)fs.textContent=`${cal.season?.icon||'🌱'} ${cal.season?.name||'—'} J${cal.day}`;const fw=$('#farmerWeather');if(fw)fw.textContent=`${w?.icon||'🌤️'} ${w?.name||'—'}`;$('#farmerBestQuality').textContent=S.stats.bestQuality?`${qlabel(S.stats.bestQuality)} · ${S.stats.bestQuality}/100`:'—';const foodDays=$('#farmerFoodDays'),foodStatus=C.foodSecurityStatus?.();if(foodDays&&foodStatus)foodDays.textContent=`${foodStatus.icon} ${Number(foodStatus.days||0).toFixed(1)} j`;const evStatus=$('#farmerEventStatus'),pending=eventLife().pending,ev=farmEvent(pending?.eventId),mods=activeEventModifiers();if(evStatus)evStatus.textContent=ev?`${ev.icon||'⚠️'} Décision`:mods.length?`✨ ${mods.length} effet${mods.length>1?'s':''}`:'🌾 Calme';$('#farmerVillageStatus').textContent=`Village niv. ${C.state.level} · plafond métier ${cap}`;$('#farmerBuildingStatus').textContent=`Niv. ${C.buildingLevel('farm')} / ${C.buildingMaxLevel('farm')} · ${C.buildingLevelDef('farm')?.name||'Ferme'}`;}
  function renderLog(){$('#farmLog').innerHTML=C.state.log.filter(x=>/🌾|🌱|💧|🧤|🧺|🗺️|🌟|👑|Fermier|Parcelle|Puzzle|Rouille|Mildiou|Puceron|Taupin|Pourriture|Saison|météo|Terre unique|Épeautre|rubis|lune|🍲|🔴|🏺|ration|Pénurie|semences protégées|Transformation|Farine|Fourrage|Malt|⚙️|Événement agricole|Gel tardif|Sécheresse|Pluies persistantes|ravageurs|Fenêtre de récolte|Grainetier|Concours agricole|Cache de semences|🌦️|🥶|🐛|🌅|♻️|📣|🏅|🗝️/.test(x.m)).slice(0,30).map(x=>`<div>${new Date(x.t).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})} — ${esc(x.m)}</div>`).join('')||'<p class="muted">La chronique agricole commencera avec la première parcelle.</p>';}
  function updateWorkshopScene(){const scene=$('#farmerScene'),label=$('#farmerSceneStatus');if(!scene)return;const active=!!S.activeLandSurvey||!!F.pendingPuzzle;scene.dataset.taskKind=active?(S.activeLandSurvey?'survey':'care'):'idle';scene.classList.toggle('is-working',active);if(label)label.textContent=active?(S.activeLandSurvey?'🗺️ Reconnaissance des terres en cours':'🌾 Intervention agricole en cours'):'🌾 Parcelles prêtes à être travaillées'; }
  function triggerWorkshopActionPulse(){const scene=$('#farmerScene');if(scene){scene.classList.remove('scene-burst');void scene.offsetWidth;scene.classList.add('scene-burst');setTimeout(()=>scene.classList.remove('scene-burst'),420);}if(!S.activeLandSurvey&&!F.pendingPuzzle){const label=$('#farmerSceneStatus');if(label)label.textContent='🪏 Intervention engagée…';}}
  function bindWorkshopActionPulse(){const host=document.querySelector('section.job-workshop');if(!host||host.dataset.scenePulseBound)return;host.dataset.scenePulseBound='1';host.addEventListener('click',ev=>{const btn=ev.target.closest('button');if(btn&&btn.closest('.job-workshop'))triggerWorkshopActionPulse();});}
  function render(){updateAll();refreshMarket();renderTop();renderPlots();renderTreatment();renderWorld();renderExploitation();renderEvents();renderKnowledge();renderCareer();renderEquipment();renderEconomy();window.VillageFarmerProcessing?.render?.();renderSpecializations();renderHighLevel();renderFood();renderProgression();renderMasterCareer();renderLog();renderPuzzle();updateWorkshopScene();window.VillageAutonomyUI?.renderForBuilding?.('farm','#jobAutonomy');C.save();}
  UI.initTabs({tabs:['activity','treatment','processing','world','exploitation','events','food','autonomy','knowledge','career','equipment','economy','specialization','highlevel','mastery','progression'],storageKey:'village_farmer_tab',renderers:{activity:renderPlots,treatment:renderTreatment,processing:()=>window.VillageFarmerProcessing?.render?.(),world:renderWorld,exploitation:renderExploitation,events:renderEvents,food:renderFood,knowledge:renderKnowledge,career:renderCareer,equipment:renderEquipment,economy:renderEconomy,specialization:renderSpecializations,highlevel:renderHighLevel,mastery:renderMasterCareer,progression:renderProgression}});if(location.hash==='#food')document.querySelector('[data-tab="food"]')?.click();if(location.hash==='#events')document.querySelector('[data-tab="events"]')?.click();
  $('#saveFarmerBtn').onclick=()=>{C.save();C.log('Sauvegarde locale effectuée depuis la Ferme.');renderLog();};
  ensurePlots();render();setInterval(()=>{updateAll();contractTick();renderTop();renderPlots();renderPuzzle();if(!$('#processingTab')?.classList.contains('hidden'))window.VillageFarmerProcessing?.render?.();if(!$('#careerTab')?.classList.contains('hidden'))renderCareer();if(!$('#exploitationTab')?.classList.contains('hidden'))renderExploitation();if(!$('#eventsTab')?.classList.contains('hidden'))renderEvents();if(!$('#highlevelTab')?.classList.contains('hidden'))renderHighLevel();if(!$('#foodTab')?.classList.contains('hidden'))renderFood();if(!$('#masteryTab')?.classList.contains('hidden'))renderMasterCareer();},1000);window.addEventListener('village:food',()=>{renderTop();if(!$('#foodTab')?.classList.contains('hidden'))renderFood();});window.addEventListener('village:autonomy',()=>window.VillageAutonomyUI?.renderForBuilding?.('farm','#jobAutonomy'));
